-- Calendar parity with server-enforced date windows and scoped approval grants.
create table public.calendar_access_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),from_date date not null,to_date date not null check(to_date>=from_date and to_date-from_date<=90),reason text not null check(length(trim(reason)) between 1 and 2000),edit_type text not null default 'Full day' check(edit_type in ('Full day','Half day')),status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid,expires_at timestamptz,created_at timestamptz not null default now());
alter table public.calendar_access_requests enable row level security;
grant select on public.calendar_access_requests to authenticated;
create policy requests_read on public.calendar_access_requests for select to authenticated using(private.is_member() and (user_id=auth.uid() or private.can_review(user_id)));
create function private.calendar_today() returns date language sql stable set search_path='' as $$ select (now() at time zone 'Asia/Kolkata')::date $$;
create function private.assert_calendar_date(p_user uuid,p_date date) returns void language plpgsql security definer set search_path='' as $$begin
 perform private.assert_member();
 if p_user<>auth.uid() and not private.can_review(p_user) then raise exception 'Calendar access is not permitted.';end if;
 if p_date is null or abs(p_date-private.calendar_today())>730 then raise exception 'Choose a date within two years.';end if;
 if p_date<private.calendar_today()-2 and not exists(select 1 from public.memberships where user_id=auth.uid() and active and role in ('manager','admin')) and not exists(select 1 from public.calendar_access_requests where user_id=p_user and status='approved' and p_date between from_date and to_date and expires_at>now()) then raise exception 'Restricted date: older than the two-day editing window. Request access from your manager.' using errcode='42501';end if;
end;$$;
create function public.calendar_access() returns jsonb language plpgsql security definer set search_path='' as $$begin perform private.assert_member();return jsonb_build_object('today',private.calendar_today(),'earliest',private.calendar_today()-2,'timezone','Asia/Kolkata','grants',coalesce((select jsonb_agg(jsonb_build_object('from_date',from_date,'to_date',to_date)) from public.calendar_access_requests where user_id=auth.uid() and status='approved' and expires_at>now()),'[]'));end;$$;
create function public.request_calendar_access(p_from date,p_to date,p_reason text,p_type text default 'Full day') returns uuid language plpgsql security definer set search_path='' as $$declare v uuid;begin perform private.assert_member();insert into public.calendar_access_requests(user_id,from_date,to_date,reason,edit_type) values(auth.uid(),p_from,p_to,p_reason,p_type) returning id into v;insert into public.notifications(user_id,title,body) select m.user_id,'Calendar access requested','An employee requested editing access for '||p_from||' to '||p_to from public.memberships m join public.memberships own on own.user_id=auth.uid() where m.active and m.user_id<>auth.uid() and (m.role='admin' or (m.role='manager' and m.department_id=own.department_id));return v;end;$$;
create function public.review_calendar_access(p_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path='' as $$declare r public.calendar_access_requests;begin perform private.assert_member();select * into r from public.calendar_access_requests where id=p_id for update;if r.id is null or r.status<>'pending' or not private.can_review(r.user_id) then raise exception 'Review is not permitted.';end if;update public.calendar_access_requests set status=case when p_approve then 'approved' else 'rejected' end,reviewed_by=auth.uid(),expires_at=case when p_approve then now()+interval '48 hours' else null end where id=p_id;insert into public.notifications(user_id,title,body) values(r.user_id,'Calendar access reviewed',case when p_approve then 'Editing access granted for 48 hours for the requested dates.' else 'Your editing request was declined.' end);perform private.audit('calendar.access_reviewed',p_id);end;$$;
create function public.grant_calendar_access(p_users uuid[],p_from date,p_to date,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare u uuid;begin perform private.assert_member();if cardinality(p_users) not between 1 and 500 then raise exception 'Choose one or more employees.';end if;foreach u in array p_users loop if not private.can_review(u) then raise exception 'Grant is not permitted.';end if;insert into public.calendar_access_requests(user_id,from_date,to_date,reason,status,reviewed_by,expires_at) values(u,p_from,p_to,p_reason,'approved',auth.uid(),now()+interval '48 hours');insert into public.notifications(user_id,title,body) values(u,'Calendar access granted','You can edit '||p_from||' to '||p_to||' for 48 hours.');end loop;end;$$;
alter table public.time_entries add column task_status text not null default 'In Progress' check(task_status in ('Pending','In Progress','Completed'));
create function private.guard_time_entry() returns trigger language plpgsql security definer set search_path='' as $$declare s public.timesheets;old_sheet public.timesheets;d date;begin
 if TG_OP<>'INSERT' then select * into old_sheet from public.timesheets where id=old.timesheet_id for update;perform private.assert_calendar_date(old_sheet.user_id,old.work_date);if old_sheet.status not in ('draft','rejected') then raise exception 'Timesheet is locked for review.';end if;end if;
 if TG_OP<>'DELETE' then select * into s from public.timesheets where id=new.timesheet_id for update;perform private.assert_calendar_date(s.user_id,new.work_date);if s.status not in ('draft','rejected') then raise exception 'Timesheet is locked for review.';end if;if new.work_date<s.week_start or new.work_date>s.week_start+6 then raise exception 'Date must be inside the selected week.';end if;end if;
 if TG_OP='DELETE' then return old;end if;
 perform pg_advisory_xact_lock(hashtextextended(s.user_id::text,0));
 if coalesce((select sum(t.minutes) from public.time_entries t join public.timesheets ts on ts.id=t.timesheet_id where ts.user_id=s.user_id and t.work_date=new.work_date and t.id<>new.id),0)+new.minutes+coalesce((select sum(l.daily_minutes) from public.leave_requests l where l.user_id=s.user_id and l.status='approved' and new.work_date between l.from_date and l.to_date),0)>1440 then raise exception 'Work and approved leave cannot exceed 24 hours per day.';end if;
 return new;
end;$$;
create trigger guard_time_entry before insert or update or delete on public.time_entries for each row execute function private.guard_time_entry();
create function public.save_calendar_entry(p_user uuid,p_date date,p_project uuid,p_description text,p_minutes integer,p_status text default 'In Progress',p_id uuid default null,p_version integer default null) returns uuid language plpgsql security definer set search_path='' as $$
declare s public.timesheets;prev public.time_entries;v uuid;old_sheet uuid;begin
 perform private.assert_calendar_date(p_user,p_date);perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_id is not null then select * into prev from public.time_entries where id=p_id for update;if prev.id is null or prev.version is distinct from p_version or not exists(select 1 from public.timesheets where id=prev.timesheet_id and user_id=p_user) then raise exception 'Entry changed or unavailable. Refresh and retry.';end if;old_sheet:=prev.timesheet_id;end if;
 if not exists(select 1 from public.projects where id=p_project and status='active') then raise exception 'Choose an active project.';end if;
 insert into public.timesheets(user_id,week_start) values(p_user,date_trunc('week',p_date)::date) on conflict(user_id,week_start) do nothing;
 select * into s from public.timesheets where user_id=p_user and week_start=date_trunc('week',p_date)::date for update;
 if s.status not in ('draft','rejected') then raise exception 'Timesheet is locked for review.';end if;
 if coalesce((select sum(minutes) from public.time_entries where timesheet_id=s.id and work_date=p_date and (p_id is null or id<>p_id)),0)+p_minutes>1440 then raise exception 'Daily total cannot exceed 24 hours.';end if;
 if p_id is null then insert into public.time_entries(timesheet_id,work_date,project_id,description,minutes,task_status) values(s.id,p_date,p_project,trim(p_description),p_minutes,p_status) returning id into v;
 else update public.time_entries set timesheet_id=s.id,work_date=p_date,project_id=p_project,description=trim(p_description),minutes=p_minutes,task_status=p_status,version=version+1 where id=p_id returning id into v;end if;
 update public.timesheets set version=version+1 where id=s.id or id=old_sheet;perform private.audit('calendar.entry_saved',v);return v;end;$$;
create function public.calendar_entry_action(p_id uuid,p_version integer,p_action text,p_date date default null) returns void language plpgsql security definer set search_path='' as $$declare e public.time_entries;u uuid;d date;begin
 perform private.assert_member();select * into e from public.time_entries where id=p_id for update;if e.id is null or e.version is distinct from p_version then raise exception 'Entry changed or unavailable.';end if;select user_id into u from public.timesheets where id=e.timesheet_id;perform private.assert_calendar_date(u,e.work_date);
 if p_action='delete' then delete from public.time_entries where id=e.id;update public.timesheets set version=version+1 where id=e.timesheet_id;
 elsif p_action='move' then perform public.save_calendar_entry(u,p_date,e.project_id,e.description,e.minutes,e.task_status,e.id,e.version);
 elsif p_action='copy' then perform public.save_calendar_entry(u,p_date,e.project_id,e.description,e.minutes,e.task_status);
 elsif p_action='extend' then
 if p_date<=e.work_date or p_date-e.work_date>31 then raise exception 'Extend to a later date within 31 days.';end if;
 for d in select generate_series(e.work_date+1,p_date,interval '1 day')::date loop perform public.save_calendar_entry(u,d,e.project_id,e.description,e.minutes,e.task_status);end loop;
 else raise exception 'Unknown calendar action.';end if;perform private.audit('calendar.'||p_action,p_id);end;$$;
alter table public.leave_requests add column leave_type text not null default 'Casual' check(leave_type in ('Casual','Sick','Earned','Emergency','Unpaid')),add column daily_minutes integer not null default 480 check(daily_minutes in (240,480)),add column version integer not null default 1;
create function private.guard_leave() returns trigger language plpgsql security definer set search_path='' as $$declare d date;begin
 if TG_OP='DELETE' then perform private.assert_calendar_date(old.user_id,old.from_date);if old.status='approved' then raise exception 'Approved leave cannot be deleted.';end if;return old;end if;
 if TG_OP='INSERT' or new.from_date<>old.from_date or new.to_date<>old.to_date or new.reason<>old.reason or new.daily_minutes<>old.daily_minutes or new.leave_type<>old.leave_type then
 if TG_OP='UPDATE' and old.status='approved' then raise exception 'Approved leave cannot be changed.';end if;
 if new.to_date-new.from_date>90 then raise exception 'Request up to 90 days.';end if;
 for d in select generate_series(new.from_date,new.to_date,interval '1 day')::date loop perform private.assert_calendar_date(new.user_id,d);end loop;
 end if;return new;end;$$;
create trigger guard_leave before insert or update or delete on public.leave_requests for each row execute function private.guard_leave();
create function public.save_calendar_leave(p_user uuid,p_from date,p_to date,p_reason text,p_type text,p_minutes integer,p_id uuid default null,p_version integer default null) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid;r public.leave_requests;begin
 perform private.assert_calendar_date(p_user,p_from);
 if p_id is null then insert into public.leave_requests(user_id,from_date,to_date,reason,leave_type,daily_minutes) values(p_user,p_from,p_to,trim(p_reason),p_type,p_minutes) returning id into v;
 else select * into r from public.leave_requests where id=p_id and user_id=p_user for update;if r.id is null or r.version is distinct from p_version or r.status='approved' then raise exception 'Leave changed or is already approved.';end if;update public.leave_requests set from_date=p_from,to_date=p_to,reason=trim(p_reason),leave_type=p_type,daily_minutes=p_minutes,status='pending',reviewed_by=null,version=version+1 where id=p_id returning id into v;end if;
 insert into public.notifications(user_id,title,body) select m.user_id,'Leave request pending','Review the request for '||p_from||' to '||p_to from public.memberships m join public.memberships own on own.user_id=p_user where m.active and m.user_id<>p_user and (m.role='admin' or (m.role='manager' and m.department_id=own.department_id));perform private.audit('calendar.leave_saved',v);return v;end;$$;
create function public.delete_calendar_leave(p_id uuid,p_version integer) returns void language plpgsql security definer set search_path='' as $$begin perform private.assert_member();delete from public.leave_requests where id=p_id and version=p_version and status<>'approved';if not found then raise exception 'Leave changed or unavailable.';end if;perform private.audit('calendar.leave_deleted',p_id);end;$$;
-- Entry points remain unavailable anonymously; private enforcement helpers are not RPCs.
revoke all on function private.calendar_today(),private.assert_calendar_date(uuid,date),private.guard_time_entry(),private.guard_leave() from public,anon,authenticated;
do $$declare f record;begin for f in select oid::regprocedure sig from pg_proc where pronamespace='public'::regnamespace and proname in ('calendar_access','request_calendar_access','review_calendar_access','grant_calendar_access','save_calendar_entry','calendar_entry_action','save_calendar_leave','delete_calendar_leave') loop execute format('revoke all on function %s from public,anon',f.sig);execute format('grant execute on function %s to authenticated',f.sig);end loop;end$$;
